import SwiftUIstruct TodayTimeline: View{//    @Bindable//    var v = TodayViewModel.shared    let timeline: [ListItemContent];    let readonly: Bool;    let deleteTimelineItem: (_ pItem: ListItemContent) -> Void;    @State    private var showAlert: Bool = false;        @State    private var selectedItem: ListItemContent?;        var body: some View    {        VStack(alignment: .leading, spacing: 10)        {            HStack            {                Text("Today")                    .font(.footnote)                    .bold()                                Spacer()                                if !timeline.isEmpty                {                    Text("\(timeline.count) logged")                        .font(.footnote)                        .foregroundStyle(.secondary)                        .contentTransition(.numericText())                        .animation(.snappy, value: timeline.count)                }            }                        if timeline.isEmpty            {                Text("Start Logging !!")                    .font(.footnote)                    .foregroundStyle(.secondary)                    .padding(.vertical, 12)            } else            {                VStack(spacing: 0)                {                    ForEach(timeline, id: \.compositeId)                    { item in                        TimelineRow(                            item: item,                            isFirst: item.compositeId == timeline.first?.compositeId,                            isLast: item.compositeId == timeline.last?.compositeId                        ) { toDelete in                            if !readonly                            {                                selectedItem = toDelete                                showAlert = true                            }                        }                        .transition(.asymmetric(                            insertion: .opacity.combined(with: .move(edge: .top)),                            removal: .opacity.combined(with: .scale(scale: 0.95))                        ))                    }                }            }        }        .animation(.spring(response: 0.35, dampingFraction: 0.8), value: timeline.map(\.compositeId))        .padding(.top)        .alert("Delete log?", isPresented: $showAlert)        {            Button("Delete", role: .destructive)            {                if let selectedItem {                    deleteTimelineItem(selectedItem)                }            }                        Button("Cancel", role: .cancel) {}        }    }}